import{_ as t,o,c as d,a5 as a}from"./chunks/framework.BwlBv862.js";const h=JSON.parse('{"title":"TikTools を開発する","description":"","frontmatter":{"title":"TikTools を開発する","docId":"developer.overview","translationKey":"developer.overview","locale":"ja","audience":"developer","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"1ee65a70172f8154eeaf60fb1a3069192769582a4ef264426d0aefaf346e8003","translationRevision":"d30e9e185b058a920cbfcb31e41a7865112d9dea11de7ff1dd58acef2f34cc69","order":0},"headers":[],"relativePath":"ja/developer/index.md","filePath":"ja/developer/index.md","lastUpdated":1794611623000}'),r={name:"ja/developer/index.md"};function i(c,e,n,s,l,p){return o(),d("div",null,[...e[0]||(e[0]=[a('<h1 id="develop-tiktools" tabindex="-1">TikTools を開発する <a class="header-anchor" href="#develop-tiktools" aria-label="Permalink to &quot;TikTools を開発する {#develop-tiktools}&quot;">​</a></h1><p>TikTools は型付き制御操作の背後に1つのネイティブ AppCore を置きます。Vue がデスクトップ、ローカルブラウザー、コントローラーの画面を描画し、Winit/Wry がウィンドウを所有します。CLI と SDK も同じ操作を使います。<a href="./setup.html">開発環境</a> を整え、変更を検証できる最小の開発サイクルを選びます。</p><h2 id="choose-an-entry-point" tabindex="-1">入口を選ぶ <a class="header-anchor" href="#choose-an-entry-point" aria-label="Permalink to &quot;入口を選ぶ {#choose-an-entry-point}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>作業</th><th>入口</th><th>確認できること</th></tr></thead><tbody><tr><td>Vue 部品とストア</td><td>Vite、Vitest、注入した ControlClient</td><td>UI の動作。ネイティブウィンドウは未検証。</td></tr><tr><td>デスクトップ連携</td><td><code>bun run start</code></td><td>開発用 WebView と IPC の連携。</td></tr><tr><td>ネイティブサービス</td><td>対象を絞った Cargo テスト</td><td>コア契約、永続化、サービス動作。</td></tr><tr><td>ヘッドレスのブラウザー接続</td><td><code>bun run dev</code></td><td>ネイティブホスト、ローカルアダプター、ペアリング付き Vite。</td></tr><tr><td>ドキュメント</td><td><code>bun scripts/task.ts docs dev</code></td><td>Markdown と分離した VitePress ビルド。</td></tr><tr><td>公開デモ</td><td>独立したデモ入口と模擬通信</td><td>配信元サービスではなく、決定的な架空シナリオ。</td></tr></tbody></table><h2 id="source-ownership" tabindex="-1">ソースの担当範囲 <a class="header-anchor" href="#source-ownership" aria-label="Permalink to &quot;ソースの担当範囲 {#source-ownership}&quot;">​</a></h2><ul><li><code>crates/tiktools-core</code>: サービス、操作、SQLite。WebView に依存しません。</li><li><code>crates/tiktools-control-api</code>: レジストリ、JSON-RPC ルーティング、IPC、機能検出。</li><li><code>crates/tiktools-desktop</code>: Winit/Wry、UI スレッド橋渡し、ライフサイクル、同梱アセット。</li><li><code>src/web/app</code>: 起動、ルーター、シェル。<code>pages</code> は <code>widgets</code> と <code>features</code> を構成し、<code>entities</code> はドメインストア・契約、<code>shared</code> は再利用 UI と基盤を所有します。</li><li><code>src/automation/contracts/generated</code>: Rust から生成したバージョン付きイベント契約。デモやガイドで同じスキーマを再定義しません。</li><li><code>packages</code>: 既存の TypeScript プラグイン SDK/UI パッケージ。プラグイン実装は外部リポジトリにあります。</li></ul><h2 id="contribution-boundary" tabindex="-1">貢献時の境界 <a class="header-anchor" href="#contribution-boundary" aria-label="Permalink to &quot;貢献時の境界 {#contribution-boundary}&quot;">​</a></h2><p>ネイティブ、ローカルブラウザー、リモートコントローラー、デモの入口を明示します。実環境の入口でホストがなければエラーであり、黙ってモックを選びません。所有スコープでリスナー、購読、タイマーを破棄します。Rust/Bun ロックファイルと必須 CI 条件を維持します。</p><p>利用者のインストールは<a href="./../user/installation.html">ユーザーガイド</a> にあります。開発時の検査だけでは実際の TikTok 接続、OBS 描画、ネイティブ WebView 互換性、2台の PC での共同操作は確認できません。</p>',9)])])}const b=t(r,[["render",i]]);export{h as __pageData,b as default};
